import pydantic

import dspy
from dspy.utils.dummies import DummyLM


class OutputField3(pydantic.BaseModel):
    subfield1: int
    subfield2: float


class TestSignature(dspy.Signature):
    input1: str = dspy.InputField()
    output1: str = dspy.OutputField()
    output2: bool = dspy.OutputField(desc="Boolean output field")
    output3: OutputField3 = dspy.OutputField(desc="Nested output field")
    output4_unannotated = dspy.OutputField(desc="Unannotated output field")


class SchemaAwareDummyLM(DummyLM):
    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True


def snapshot(signature):
    return {
        name: (field.annotation, dict(field.json_schema_extra))
        for name, field in signature.output_fields.items()
    }


adapter = dspy.JSONAdapter()
lm = SchemaAwareDummyLM(
    [
        {
            "output1": "hello",
            "output2": True,
            "output3": {"subfield1": 1, "subfield2": 2.5},
            "output4_unannotated": "plain",
        }
    ],
    adapter=adapter,
)
dspy.configure(lm=lm, adapter=adapter)

predictor = dspy.Predict(TestSignature)
before = snapshot(TestSignature)
result = predictor(input1="Test input")
after = snapshot(TestSignature)

response_format = lm.history[-1]["kwargs"]["response_format"]

assert result.output1 == "hello"
assert issubclass(response_format, pydantic.BaseModel)
assert set(response_format.model_fields) == {"output1", "output2", "output3", "output4_unannotated"}
assert before == after

